    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        scwin.emailCheck(selfVar)

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf95100.ipt_newEmail01_onkeydown' }); }
};

