///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name tx_save_down
 * @description save down 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_save_down = async function () {
    try { return await $c.data.downFile("/common/downinfo.do?method=downInfoSave", "", ($c.util.getComponent("dma_saveDownReq") ? $c.util.getComponent("dma_saveDownReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

/**
 * @method
 * @name tx_check_form
 * @description check form 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_check_form = async function () {
    try { return await $c.data.downFile("/common/downinfo.do?method=searchDownloadInfo", "", ($c.util.getComponent("dma_checkFormReq") ? $c.util.getComponent("dma_checkFormReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

/**
 * @method
 * @name emailCheck
 * @description 표준 API 조합으로 새로 작성한 검사 함수
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.emailCheck = function (obj) { try { const t = (obj && obj.value != null) ? obj : ((obj && (obj.target || obj.srcElement)) || null); if (t && t.value != null) { t.value = String(t.value).replace(/[^A-Za-z0-9.@_%+\\-]/g, ''); } } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'authored-fn' }); return; } };

/**
 * @method
 * @name save_down
 * @description save down 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save_down = async function () {
    if ($c.util.getComponent('ipt_emailCheck').getValue() === "N") {
        await $c.win.alert("이메일 중복 체크를 하세요");
        $c.util.getComponent("ipt_emailCheck").focus();
        return;
    }
    const mail01 = $c.util.getComponent('ipt_newEmail01').getValue();
    const mail02 = $c.util.getComponent('ipt_newEmail02').getValue();
    const mail = mail01 + "@" + mail02;
    $c.util.getComponent('ipt_encrypEmail').setValue(mail);
    const ph01 = $c.util.getComponent('ipt_ph01').getValue();
    const ph02 = $c.util.getComponent('ipt_ph02').getValue();
    const ph03 = $c.util.getComponent('ipt_ph03').getValue();
    const tel_no = ph01 + "-" + ph02 + "-" + ph03;
    $c.util.getComponent('ipt_telNo').setValue(tel_no);
    const fax01 = $c.util.getComponent('ipt_fax01').getValue();
    const fax02 = $c.util.getComponent('ipt_fax02').getValue();
    const fax03 = $c.util.getComponent('ipt_fax03').getValue();
    const fax_no = fax01 + "-" + fax02 + "-" + fax03;
    $c.util.getComponent('ipt_faxNo').setValue(fax_no);
    if (($c.util.getComponent('ipt_newEmail01').getValue() == null ? '' : String($c.util.getComponent('ipt_newEmail01').getValue())) === '' || ($c.util.getComponent('ipt_newEmail02').getValue() == null ? '' : String($c.util.getComponent('ipt_newEmail02').getValue())) === '') {
        await $c.win.alert("이메일을 입력하세요");
        $c.util.getComponent("ipt_newEmail01").focus();
        return;
    }
    if (($c.util.getComponent('ipt_wrtrNm').getValue() == null ? '' : String($c.util.getComponent('ipt_wrtrNm').getValue())) === '') {
        await $c.win.alert("이름을 입력하세요");
        $c.util.getComponent("ipt_wrtrNm").focus();
        return;
    }
    if (($c.util.getComponent('ipt_comNm').getValue() == null ? '' : String($c.util.getComponent('ipt_comNm').getValue())) === '') {
        await $c.win.alert("회사명을 입력하세요");
        $c.util.getComponent("ipt_comNm").focus();
        return;
    }
    if (($c.util.getComponent('ipt_ph01').getValue() == null ? '' : String($c.util.getComponent('ipt_ph01').getValue())) === '' || ($c.util.getComponent('ipt_ph02').getValue() == null ? '' : String($c.util.getComponent('ipt_ph02').getValue())) === '' || ($c.util.getComponent('ipt_ph03').getValue() == null ? '' : String($c.util.getComponent('ipt_ph03').getValue())) === '') {
        await $c.win.alert("전화번호를 입력하세요");
        ($c.util.getComponent('ipt_ph01') && $c.util.getComponent('ipt_ph01').setFocus ? $c.util.getComponent('ipt_ph01').setFocus() : $c.util.getComponent('ipt_ph01').focus());
        return;
    }
    if (($c.util.getComponent('ipt_rsnContn').getValue() == null ? '' : String($c.util.getComponent('ipt_rsnContn').getValue())) === '') {
        await $c.win.alert("사용목적을 입력하세요");
        $c.util.getComponent("ipt_rsnContn").focus();
        return;
    }
    if ($c.util.getComponent('ipt_dnldGrpTpCd').getValue() === "03") {
        if ($c.util.getComponent('ipt_dnldInstTpCd').getValue() === "04") {
            $c.util.getComponent('ipt_dnldInstTpCd').setValue("06");
        } else {
            if ($c.util.getComponent('ipt_dnldInstTpCd').getValue() === "05") {
                $c.util.getComponent('ipt_dnldInstTpCd').setValue("07");
            } else {
                if ($c.util.getComponent('ipt_dnldInstTpCd').getValue() === "06") {
                    $c.util.getComponent('ipt_dnldInstTpCd').setValue("09");
                } else {
                    if ($c.util.getComponent('ipt_dnldInstTpCd').getValue() === "07") {
                        $c.util.getComponent('ipt_dnldInstTpCd').setValue("13");
                    } else {
                        if ($c.util.getComponent('ipt_dnldInstTpCd').getValue() === "08") {
                            $c.util.getComponent('ipt_dnldInstTpCd').setValue("10");
                        } else {
                            if ($c.util.getComponent('ipt_dnldInstTpCd').getValue() === "10") {
                                $c.util.getComponent('ipt_dnldInstTpCd').setValue("04");
                            } else {
                                if ($c.util.getComponent('ipt_dnldInstTpCd').getValue() === "11") {
                                    $c.util.getComponent('ipt_dnldInstTpCd').setValue("08");
                                } else {
                                    if ($c.util.getComponent('ipt_dnldInstTpCd').getValue() === "16") {
                                        $c.util.getComponent('ipt_dnldInstTpCd').setValue("14");
                                    } else {
                                        if ($c.util.getComponent('ipt_dnldInstTpCd').getValue() === "12") {
                                            $c.util.getComponent('ipt_dnldInstTpCd').setValue("05");
                                        } else {
                                            if ($c.util.getComponent('ipt_dnldInstTpCd').getValue() === "14") {
                                                $c.util.getComponent('ipt_dnldInstTpCd').setValue("12");
                                            } else {
                                                if ($c.util.getComponent('ipt_dnldInstTpCd').getValue() === "18") {
                                                    $c.util.getComponent('ipt_dnldInstTpCd').setValue("15");
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }
    const form = (document.JLDINF95100 || { elements: [] });
    form.method = 'post';
    form.action = "/common/downinfo.do?method=downInfoSave";
    form.target = '_self';
    await scwin.tx_save_down();
};

/**
 * @method
