};

/**
 * @method
 * @name email_DualCheck
 * @description email Dual Check 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.email_DualCheck = async function () {
    const mail01 = $c.util.getComponent('ipt_newEmail01').getValue();
    const mail02 = $c.util.getComponent('ipt_newEmail02').getValue();
    const mail = mail01 + "@" + mail02;
    let dnld_inst_tp_cd = $c.util.getComponent('ipt_dnldInstTpCd').getValue();
    $c.util.getComponent('ipt_encrypEmail').setValue(mail);
    if (($c.util.getComponent('ipt_newEmail01').getValue() == null ? '' : String($c.util.getComponent('ipt_newEmail01').getValue())) === '' || ($c.util.getComponent('ipt_newEmail02').getValue() == null ? '' : String($c.util.getComponent('ipt_newEmail02').getValue())) === '') {
        await $c.win.alert("이메일을 입력하세요");
        $c.util.getComponent("ipt_newEmail01").focus();
        return;
    }
    if ($c.util.getComponent('ipt_dnldGrpTpCd').getValue() === "03") {
        if (dnld_inst_tp_cd === "04") {
            dnld_inst_tp_cd = "06";
        } else {
            if (dnld_inst_tp_cd === "05") {
                dnld_inst_tp_cd = "07";
            } else {
                if (dnld_inst_tp_cd === "06") {
                    dnld_inst_tp_cd = "09";
                } else {
                    if (dnld_inst_tp_cd === "07") {
                        dnld_inst_tp_cd = "13";
                    } else {
                        if (dnld_inst_tp_cd === "08") {
                            dnld_inst_tp_cd = "10";
                        } else {
                            if (dnld_inst_tp_cd === "10") {
                                dnld_inst_tp_cd = "04";
                            } else {
                                if (dnld_inst_tp_cd === "11") {
                                    dnld_inst_tp_cd = "08";
                                } else {
                                    if (dnld_inst_tp_cd === "16") {
                                        dnld_inst_tp_cd = "14";
                                    } else {
                                        if (dnld_inst_tp_cd === "12") {
                                            dnld_inst_tp_cd = "05";
                                        } else {
                                            if (dnld_inst_tp_cd === "14") {
                                                dnld_inst_tp_cd = "12";
                                            } else {
                                                if (dnld_inst_tp_cd === "18") {
                                                    dnld_inst_tp_cd = "15";
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }
    const form = (document.JLDINF95100 || { elements: [] });
    const url = "/common/downcheck.do?method=downloadEmailCheck";
    const params = "encryp_email=" + mail + "&dnld_inst_tp_cd=" + dnld_inst_tp_cd;
    $.post(url, params, async function(obj) {
            if (obj === '') {
                await $c.win.alert("조회 데이터가 없습니다.");
            } else {
                const jsonData = (typeof obj === "string" ? (typeof obj === "string" ? JSON.parse(obj) : obj) : obj);
                let checkCnt = 0;
                if (jsonData.cnt != null) {
                    checkCnt = Number(jsonData.cnt);
                }
                if (checkCnt > 0) {
                    $c.util.getComponent('ipt_emailCheck').setValue("N");
                    await $c.win.alert("중복된 이메일입니다.\n이메일을 확인하세요");
                } else {
                    $c.util.getComponent('ipt_emailCheck').setValue("Y");
                    await $c.win.alert("사용가능한 이메일입니다..");
                }
            }
    });
};

