                    } else {
                        if (dnld_inst_tp_cd === "08") {
                            $c.util.getComponent('ipt_dnldInstTpCd').setValue("10");
                        } else {
                            if (dnld_inst_tp_cd === "10") {
                                $c.util.getComponent('ipt_dnldInstTpCd').setValue("04");
                            } else {
                                if (dnld_inst_tp_cd === "11") {
                                    $c.util.getComponent('ipt_dnldInstTpCd').setValue("08");
                                } else {
                                    if (dnld_inst_tp_cd === "16") {
                                        $c.util.getComponent('ipt_dnldInstTpCd').setValue("14");
                                    } else {
                                        if (dnld_inst_tp_cd === "12") {
                                            $c.util.getComponent('ipt_dnldInstTpCd').setValue("05");
                                        } else {
                                            if (dnld_inst_tp_cd === "14") {
                                                $c.util.getComponent('ipt_dnldInstTpCd').setValue("12");
                                            } else {
                                                if (dnld_inst_tp_cd === "18") {
                                                    $c.util.getComponent('ipt_dnldInstTpCd').setValue("15");
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }
    const form = (document.JLDINF95100 || { elements: [] });
    form.action = "/common/downinfo.do?method=searchDownloadInfo";
    form.target = '_self';
    await scwin.tx_check_form();
};

/**
 * @method
 * @name opener
 * @description 부모 화면 scope(browserPopup/pageFramePopup 공통 — $c.win.getOpenerScope). 단독 진입이거나 부모가 닫혀 없으면
 * @returns {Object} 부모 화면 scope 또는 빈 scope
 * @hidden N
 */
scwin.opener = function () {
    const scope = ($c.win && $c.win.getOpenerScope) ? $c.win.getOpenerScope() : null;
    return scope || { getComponentById: function () { return null; }, scwin: {} };
};

/**
 * @method
 * @name openerScwin
 * @description 부모 화면의 scwin(함수·전역 접근용). 부모가 없으면 빈 객체
 * @returns {Object} 부모 scwin 또는 {}
 * @hidden N
 */
scwin.openerScwin = function () {
    return scwin.opener().scwin || {};
};
